import json
from pathlib import Path

CONTACTS_FILE = Path("contacts.json")

def load_contacts():
    if not CONTACTS_FILE.exists():
        return []

    try:
        data = json.loads(CONTACTS_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        print(f"Could not load contacts: {error}")
        return []

    if isinstance(data, dict):
        data = data.get("contacts", [])
    if not isinstance(data, list):
        return []

    contacts = []
    for item in data:
        if isinstance(item, str) and item.strip():
            contacts.append({"name": item.strip(), "phone": "", "email": ""})
        elif isinstance(item, dict) and str(item.get("name", "")).strip():
            contacts.append({
                "name": str(item.get("name", "")).strip(),
                "phone": str(item.get("phone", "")).strip(),
                "email": str(item.get("email", "")).strip()
            })
    return contacts

def save_contacts(contacts):
    try:
        CONTACTS_FILE.write_text(
            json.dumps(contacts, indent=2, ensure_ascii=False),
            encoding="utf-8"
        )
        return True
    except OSError as error:
        print(f"Could not save contacts: {error}")
        return False

def add_contact(contacts):
    name = input("Name: ").strip()
    phone = input("Phone: ").strip()
    email = input("Email: ").strip()

    if not name:
        print("Name is required.")
        return

    contacts.append({
        "name": name,
        "phone": phone,
        "email": email
    })
    if save_contacts(contacts):
        print("Contact saved.")

def list_contacts(contacts):
    if not contacts:
        print("No contacts yet.")
        return

    for index, contact in enumerate(contacts, start=1):
        print(f"{index}. {contact['name']} | {contact.get('phone', '')} | {contact.get('email', '')}")

def search_contacts(contacts, query):
    query = query.strip().lower()
    if not query:
        print("Search text cannot be empty.")
        return

    matches = [
        contact
        for contact in contacts
        if query in contact.get("name", "").lower()
    ]
    list_contacts(matches)

def get_contact_index(contacts, raw_index):
    try:
        index = int(raw_index) - 1
    except ValueError:
        print("Enter a valid contact number.")
        return None

    if index < 0 or index >= len(contacts):
        print("Contact number is out of range.")
        return None
    return index

def edit_contact(contacts):
    list_contacts(contacts)
    if not contacts:
        return

    index = get_contact_index(contacts, input("Contact number to edit: ").strip())
    if index is None:
        return

    contact = contacts[index]
    name = input(f"Name [{contact['name']}]: ").strip()
    phone = input(f"Phone [{contact.get('phone', '')}]: ").strip()
    email = input(f"Email [{contact.get('email', '')}]: ").strip()

    if name:
        contact["name"] = name
    if phone:
        contact["phone"] = phone
    if email:
        contact["email"] = email

    if not contact["name"].strip():
        print("Name cannot be empty.")
        return
    if save_contacts(contacts):
        print("Contact updated.")

def delete_contact(contacts):
    list_contacts(contacts)
    if not contacts:
        return

    index = get_contact_index(contacts, input("Contact number to delete: ").strip())
    if index is None:
        return
    removed = contacts.pop(index)
    if save_contacts(contacts):
        print(f"Deleted: {removed['name']}")

def print_help():
    print("Commands: add, list, search, edit, delete, help, exit")

def main():
    contacts = load_contacts()
    print("Contact Book")
    print_help()

    while True:
        try:
            command = input("> ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print("\nGoodbye.")
            break

        if command == "add":
            add_contact(contacts)
        elif command == "list":
            list_contacts(contacts)
        elif command == "search":
            search_contacts(contacts, input("Search: ").strip())
        elif command == "edit":
            edit_contact(contacts)
        elif command == "delete":
            delete_contact(contacts)
        elif command == "help":
            print_help()
        elif command in {"exit", "quit"}:
            save_contacts(contacts)
            print("Goodbye.")
            break
        else:
            print("Unknown command. Type 'help' for commands.")

if __name__ == "__main__":
    main()
